    match state { crate::kernel::Json::Object(fields) => crate::kernel::Json::Object(fields.into_iter().map(|(k, v)| { let new_v = match k.as_str() { "key" => match v { crate::kernel::Json::Object(fields) => fields.into_iter().find(|(k, _)| k == "value").map_or(crate::kernel::Json::Null, |(_, field_value)| field_value), other => other }, "panels" => match v { crate::kernel::Json::Array(items) => crate::kernel::Json::Array(items.into_iter().map(|item| match item { crate::kernel::Json::Object(fields) => crate::kernel::Json::Object(fields.into_iter().map(|(k, v)| { let new_v = match k.as_str() { "kind" => v, "title" => v, "note" => match v { crate::kernel::Json::Object(fields) => crate::kernel::Json::Object(fields.into_iter().map(|(k, v)| { let new_v = match k.as_str() { "text" => v, "tone" => v, "link" => match v { crate::kernel::Json::Object(fields) => crate::kernel::Json::Object(fields.into_iter().map(|(k, v)| { let new_v = match k.as_str() { "href" => v, "label" => v, _ => v }; (k, new_v) }).collect()), other => other }, _ => v }; (k, new_v) }).collect()), other => other }, "cells" => match v { crate::kernel::Json::Array(items) => crate::kernel::Json::Array(items.into_iter().map(|item| match item { crate::kernel::Json::Object(fields) => crate::kernel::Json::Object(fields.into_iter().map(|(k, v)| { let new_v = match k.as_str() { "label" => v, "note" => match v { crate::kernel::Json::Object(fields) => crate::kernel::Json::Object(fields.into_iter().map(|(k, v)| { let new_v = match k.as_str() { "text" => v, "tone" => v, "link" => match v { crate::kernel::Json::Object(fields) => crate::kernel::Json::Object(fields.into_iter().map(|(k, v)| { let new_v = match k.as_str() { "href" => v, "label" => v, _ => v }; (k, new_v) }).collect()), other => other }, _ => v }; (k, new_v) }).collect()), other => other }, _ => v }; (k, new_v) }).collect()), other => other }).collect()), other => other }, _ => v }; (k, new_v) }).collect()), other => other }).collect()), other => other }, _ => v }; (k, new_v) }).collect()), other => other }
